<?php
namespace Tests\Feature;use App\Models\Product;use App\Services\ProductImport\ProductMatcher;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class ProductMatcherTest extends TestCase {use RefreshDatabase;public function test_ean_exact_matches():void{$p=Product::create(['brand'=>'ASICS','name'=>'ASICS GEL-KAYANO 32','model'=>'GEL-KAYANO 32','ean'=>'123','slug'=>'kayano']);$r=(new ProductMatcher)->match(['brand'=>'ASICS','model'=>'OTHER','ean'=>'123']);$this->assertSame($p->id,$r->productId);$this->assertSame(1.0,$r->confidence);}public function test_conflicting_ean_does_not_name_match():void{Product::create(['brand'=>'ASICS','name'=>'ASICS GEL-KAYANO 32','model'=>'GEL-KAYANO 32','ean'=>'123','slug'=>'kayano']);$r=(new ProductMatcher)->match(['brand'=>'ASICS','model'=>'GEL-KAYANO 32','ean'=>'999']);$this->assertNull($r->productId);$this->assertSame('rejected',$r->status);}public function test_different_manufacturer_codes_do_not_merge_on_model():void{Product::create(['brand'=>'ASICS','name'=>'ASICS NOVABLAST 6','model'=>'NOVABLAST 6','mpn'=>'1011C243-001','slug'=>'novablast']);$r=(new ProductMatcher)->match(['brand'=>'ASICS','model'=>'NOVABLAST 6','mpn'=>'1012C008-500']);$this->assertNull($r->productId);}}
